        // turn end reuses it.
        let steps = fresh_then_reuse_steps(&dir, 142, 2);
        let mut rig = Rig::make_in(dir.clone(), steps, |config| {
            set_role_harness(config, ExecutionRole::Implement, Harness::Opencode);
        });
